import sys
# Mock the library to check if my code would work
class MockValidated:
    def __init__(self, email):
        self.normalized = email.split('@')[0] + '@' + email.split('@')[1].lower()
def validate_email(email):
    if '@' not in email:
        raise Exception('Invalid')
    return MockValidated(email)
class EmailNotValidError(Exception):
    pass

# Now run the logic from the handler
def handle_validate_email(params):
    email = params.get('email')
    if not isinstance(email, str):
        return 400, {'valid': False, 'error': 'invalid email'}
    try:
        validated = validate_email(email)
        email_normalized = validated.normalized
        return 200, {'valid': True, 'email': email_normalized}
    except Exception:
        return 400, {'valid': False, 'error': 'invalid email'}

print(handle_validate_email({'email': 'Test@Example.Com'}))
